import time
started_mono=time.monotonic()
started_epoch=time.time()
import os,sys,json,pathlib,hashlib,stat,socket,subprocess,secrets,string,platform,base64,re
TASK='RES-BEE-FD-PROBE-001'
ACTUAL='01a11945-ec1a-7281-8e01-a2f08ffc2c90'
R=pathlib.Path('/Volumes/WD_BLACK_SN7100_2TB_Media/UnityProj/FightMatch')
E=R/'TestArtifacts/FightMatch/RES-BEE-FD-PROBE-001'
OUT=E/'probe.json'
deadline=started_mono+15
sockets=[];nodes={};directories={};snapshots=[];failure=None
def stamp(p):
 s=p.lstat()
 return {'dev':s.st_dev,'ino':s.st_ino,'uid':s.st_uid,'gid':s.st_gid,'mode':s.st_mode,'size':s.st_size,'mtimeNs':s.st_mtime_ns,'ctimeNs':s.st_ctime_ns}
def stable(a,b):
 return all(a[k]==b[k] for k in ('dev','ino','uid','gid','mode'))
def budget():
 if time.monotonic()>=deadline-2:raise TimeoutError('Probe work deadline; cleanup reserve')
def create_socket():
 budget()
 s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM)
 s.settimeout(0.5);sockets.append(s)
 return s
def fd_meta(item):
 s=item['socket'];f=os.fstat(s.fileno())
 return {'role':item['role'],'fd':s.fileno(),'expectedFullPath':item['path'],'pathRelation':item['relation'],'fstat':{'dev':f.st_dev,'ino':f.st_ino,'uid':f.st_uid,'gid':f.st_gid,'mode':f.st_mode,'isSocket':stat.S_ISSOCK(f.st_mode)},'getsockname':s.getsockname()}
def observe(label,items):
 budget()
 argv=['/usr/sbin/lsof','-a','-p',str(os.getpid()),'-U','-Fpcftn']
 snap={'stage':label,'argv':argv,'startedEpoch':time.time(),'startedMonotonic':time.monotonic(),'knownFDs':[fd_meta(i) for i in items],'pathLstats':{str(p):stamp(p) for p in nodes}}
 snapshots.append(snap)
 timeout=min(2,deadline-2-time.monotonic());snap['timeoutSeconds']=timeout
 if timeout<=0:raise TimeoutError('No lsof time remaining')
 try:
  proc=subprocess.run(argv,capture_output=True,timeout=timeout)
  stdout,stderr=proc.stdout,proc.stderr;snap['exitCode']=proc.returncode
 except subprocess.TimeoutExpired as e:
  stdout=e.stdout or b'';stderr=e.stderr or b'';snap['exitCode']=None;snap['timedOut']=True
 finally:
  snap['finishedEpoch']=time.time();snap['finishedMonotonic']=time.monotonic()
 snap['rawStdout']=stdout.decode('utf-8','replace');snap['rawStderr']=stderr.decode('utf-8','replace')
 snap['rawStdoutBase64']=base64.b64encode(stdout).decode();snap['rawStderrBase64']=base64.b64encode(stderr).decode()
 records=[];pid=None;cur=None
 for line in snap['rawStdout'].splitlines():
  if not line:continue
  if line[0]=='p':pid=line[1:];cur=None
  elif line[0]=='f':
   token=line[1:];m=re.fullmatch(r'([0-9]+)[rwu]?',token)
   cur={'ownerPid':pid,'fdToken':token,'fd':int(m.group(1)) if m else None,'t':[],'n':[]};records.append(cur)
  elif cur is not None and line[0] in ('t','n'):cur[line[0]].append(line[1:])
 comparisons=[]
 for known in snap['knownFDs']:
  matches=[r for r in records if r['ownerPid']==str(os.getpid()) and r['fd']==known['fd']]
  comparisons.append({'role':known['role'],'fd':known['fd'],'expectedFullPath':known['expectedFullPath'],'pathRelation':known['pathRelation'],'matchingFDRecords':matches,'exactFullPathMatch':len(matches)==1 and matches[0]['n']==[known['expectedFullPath']],'unixTypeMatch':len(matches)==1 and matches[0]['t']==['unix']})
 snap['comparisons']=comparisons
 snap['afterFDs']=[fd_meta(i) for i in items]
 snap['allKnownFDsStable']=all(x['fd']==y['fd'] and x['fstat']==y['fstat'] for x,y in zip(snap['knownFDs'],snap['afterFDs']))
 if snap.get('timedOut'):raise TimeoutError('lsof exceeded its single-call limit')
 if proc.returncode!=0 or stderr:raise RuntimeError('lsof failed or emitted stderr')
 if not snap['allKnownFDsStable']:raise RuntimeError('Own FD identity changed during observation')
 budget()
