report={'task':TASK,'owner':{'thread':'01a0fdbc-bf1e-7780-8f7f-dec13d6d590c','host':'local','turn':ACTUAL},'pid':os.getpid(),'uid':os.getuid(),'platform':platform.platform(),'python':{'executable':sys.executable,'version':sys.version},'source':SOURCE,'sourceSHA256':hashlib.sha256(SOURCE.encode()).hexdigest(),'inlineCommand':inline_command,'inlineCommandSHA256':hashlib.sha256(inline_command.encode()).hexdigest(),'startedEpoch':started_epoch,'startedMonotonic':started_mono,'limitSeconds':15,'maxLsofCalls':3,'snapshots':snapshots,'cleanup':[]}
if os.path.lexists(E):raise RuntimeError('Evidence directory must be fresh')
E.mkdir(mode=0o700)
try:
 budget()
 tool=pathlib.Path('/usr/sbin/lsof');tool_stat=stamp(tool);data=tool.read_bytes()
 report['lsof']={'path':str(tool),'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),'lstat':tool_stat}
 if len(data)!=470608 or report['lsof']['sha256']!='deff85c7b4750a948a69fcd48eae3b394a37575e5048e5eb4a35b7a0482c3dc8':raise RuntimeError('Frozen lsof identity mismatch')
 parent=pathlib.Path('/private/tmp')
 if parent.resolve()!=parent:raise RuntimeError('TMP parent is not canonical')
 root=parent/('fm-bee-fd.'+''.join(secrets.choice(string.ascii_letters+string.digits) for _ in range(8)))
 root.mkdir(mode=0o700);directories[root]=stamp(root)
 child=root/(''.join(secrets.choice(string.ascii_lowercase) for _ in range(8))+'.'+''.join(secrets.choice(string.ascii_lowercase) for _ in range(3)))
 child.mkdir(mode=0o700);directories[child]=stamp(child)
 for p,s in directories.items():
  if p.resolve()!=p or not stat.S_ISDIR(s['mode']) or stat.S_IMODE(s['mode'])!=0o700 or s['uid']!=os.getuid():raise RuntimeError('New directory identity mismatch')
 report['directories']={str(p):s for p,s in directories.items()}
 listeners=[];connected=[]
 for channel in ('htc','cth'):
  p=child/('ipc_'+str(os.getpid())+'_'+channel)
  if os.path.lexists(p):raise RuntimeError('Socket path unexpectedly exists')
  s=create_socket();s.bind(str(p));nodes[p]=stamp(p)
  if not stat.S_ISSOCK(nodes[p]['mode']) or nodes[p]['uid']!=os.getuid():raise RuntimeError('Own bound socket metadata mismatch')
  s.listen(1)
  listeners.append({'role':channel+'.listener','socket':s,'path':str(p),'relation':'bound local path'})
 report['socketPreimages']={str(p):s for p,s in nodes.items()}
 observe('1_listening',listeners)
 for item in listeners:
  budget();client=create_socket();client.connect(item['path'])
  accepted,address=item['socket'].accept();accepted.settimeout(0.5);sockets.append(accepted)
  channel=item['role'].split('.')[0]
  connected.extend([{'role':channel+'.client','socket':client,'path':item['path'],'relation':'connected peer path; local endpoint unbound'},{'role':channel+'.accepted','socket':accepted,'path':item['path'],'relation':'accepted local path'}])
 observe('2_connected_listeners_open',listeners+connected)
 for item in listeners:item['socket'].close()
 observe('3_connected_listeners_closed',connected)
except BaseException as error:
 failure={'type':type(error).__name__,'message':str(error)}
finally:
 for s in reversed(sockets):
  try:
   fd=s.fileno()
   if fd>=0:s.close();report['cleanup'].append({'action':'close_owned_fd','fd':fd,'ok':True})
  except BaseException as error:report['cleanup'].append({'action':'close_owned_fd','ok':False,'error':str(error)})
 for p,original in nodes.items():
  try:
   now=stamp(p)
   if not stable(original,now) or not stat.S_ISSOCK(now['mode']):raise RuntimeError('Socket identity conflict; preserved')
   p.unlink();report['cleanup'].append({'action':'unlink_owned_socket','path':str(p),'preUnlinkLstat':now,'ok':True})
  except BaseException as error:report['cleanup'].append({'action':'unlink_owned_socket','path':str(p),'ok':False,'error':str(error)})
 for p in reversed(list(directories)):
  try:
   now=stamp(p)
   if not stable(directories[p],now) or not stat.S_ISDIR(now['mode']):raise RuntimeError('Directory identity conflict; preserved')
   if list(p.iterdir()):raise RuntimeError('Directory not empty; preserved')
   p.rmdir();report['cleanup'].append({'action':'remove_owned_empty_directory','path':str(p),'ok':True})
  except BaseException as error:report['cleanup'].append({'action':'remove_owned_empty_directory','path':str(p),'ok':False,'error':str(error)})
 report['failure']=failure
 report['cleanupComplete']=all(v['ok'] for v in report['cleanup'])
 report['observedLsofCalls']=len(snapshots)
 complete=len(snapshots)==3 and failure is None and report['cleanupComplete']
 exact=complete and all(c['exactFullPathMatch'] and c['unixTypeMatch'] for s in snapshots for c in s['comparisons'])
 report['observationStatus']='EXACT_PATH_OBSERVED' if exact else 'NOT_OBSERVABLE'
 report['executionStatus']='COMPLETED' if complete else 'FAILED'
 report['notProofOfBeeImplementation']=True
 report['finishedEpochThroughCleanup']=time.time();report['finishedMonotonicThroughCleanup']=time.monotonic()
 report['elapsedSecondsThroughCleanup']=report['finishedMonotonicThroughCleanup']-started_mono
 if report['elapsedSecondsThroughCleanup']>15:report['executionStatus']='FAILED';report['deadlineExceeded']=True
 payload=(json.dumps(report,ensure_ascii=False,indent=2)+'\n').encode()
 if len(payload)>65536:raise RuntimeError('Evidence would exceed64KiB; refused')
 with OUT.open('xb') as f:f.write(payload);f.flush();os.fsync(f.fileno())
 identity={'bytes':len(payload),'sha256':hashlib.sha256(payload).hexdigest()}
 end=time.monotonic()
 result={'task':TASK,'actual':ACTUAL,'pid':os.getpid(),'executionStatus':report['executionStatus'],'observationStatus':report['observationStatus'],'failure':failure,'lsofCalls':len(snapshots),'cleanupComplete':report['cleanupComplete'],'elapsedSecondsThroughEvidence':end-started_mono,'within15Seconds':end-started_mono<=15,'probe':{'path':str(OUT),**identity},'comparisonsByStage':[{'stage':s['stage'],'exitCode':s.get('exitCode'),'knownFDs':len(s['knownFDs']),'exactFullPathMatches':sum(c['exactFullPathMatch'] for c in s.get('comparisons',[]))} for s in snapshots]}
 print(json.dumps(result,ensure_ascii=False),flush=True)
 sys.exit(0 if complete and end-started_mono<=15 else 1)

